import{_ as a,a0 as o,w as l,s as i,ao as d,I as r,x as s,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"命令列星期二 —— 第三篇 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二 —— 第三篇 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二 —— 第三篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二 —— 第三篇 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140702 Command Line Tuesdays--Part Three","title":"命令列星期二 —— 第三篇","tag":"201407","desc":""},"relativePath":"201407/20140702 Command Line Tuesdays--Part Three.md","filePath":"[post].md"}'),g={name:"201407/20140702 Command Line Tuesdays--Part Three.md"};function m(u,e,h,T,f,w){const t=o("Link");return l(),i("div",null,[e[11]||(e[11]=d(`<h1 id="命令列星期二-——-第三篇" tabindex="-1">命令列星期二 —— 第三篇 <a class="header-anchor" href="#命令列星期二-——-第三篇" aria-label="Permalink to “命令列星期二 —— 第三篇”">​</a></h1><p>今天，肖茨先生將帶領我們遊歷文件系統的第一部分。我們將學到如何訪問、列出目錄內的文件，以及首次介紹一些選項的運用。OK，讓我們開始學習這周的第一個命令。</p><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to “ls”">​</a></h3><p>ls 是一個用來列出目錄內文件的命令。通過添加<strong>選項</strong>來實現多種不同的用途。簡單起見，你可以只需鍵入 ls 。但是，你也可以在命令後面添加一個選項，它會幫助你修飾你的命令。如果你想要隨意擺弄一些信息時，這會幫到你的。舉例來説，當你要從一個命令的大量輸出中找尋指定信息，你可以用選項縮小範圍來實現。</p><p>這就是選項的基礎概念。我們可以用下面書寫格式表示：</p><pre><code>command(命令) -option(選項) argument(參數)
</code></pre><p>命令，恩...，我們可以輸入 pwd、 ls， 或者我們到目前為止所有學過的命令。</p><p>以上我們已經闡述了選項的目的。但是我們需要注意一下書寫格式：在前頭添加一個破折號。所以，如果選項為 l, 你需要在命令後鍵入<strong>-l</strong>。</p><p><strong>參數</strong>是一個命令的操作對象（在這個例子中，它是一個目錄，我們將會學到如何瀏覽它們）。</p><p>接着，讓我們嘗試在主目錄裏嘗試用 ls 命令列出 /etc 目錄內容。這次我們先不添加選項。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/Screenshot-30.-06.-2014-184127.png" alt=""></p><p>就這樣，列出了一大堆的文件。它們還根據顏色進行了分類。藍色的是目錄，白色的為普通文件，綠色的似乎是某種 shell 腳本文件。除此之外，還有其他不同的顏色來代表不同的文件類型。</p><p>接下來，你可以在剛才的命令裏添加 -l 選項。添加選項 -l 後也會列出同樣的文件和目錄，但是以長格式方式輸出。如果你需要查看更多信息的話，這個選項將是不錯的選擇。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/Screenshot-30.-06.-2014-184542.png" alt=""></p><h3 id="長格式" tabindex="-1">長格式 <a class="header-anchor" href="#長格式" aria-label="Permalink to “長格式”">​</a></h3><p>這樣，用了長格式後，你可以看到更詳細的信息，以及在每行開頭類似-rw-r--r-- 令人抓狂的標示。實際上，這只是一種組合，代表了各種意義的信息。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/Screenshot-30.-06.-2014-184829.png" alt=""></p><p>(File Name)就是文件的名稱。（Modification time）是文件最後修改的時間。(Size) 用 byte 計量的文件大小。(Group) 是組的名稱，和擁有者一起構成文件權限。(Owner) 是文件擁有者的名稱。最最重要的…</p><p>###…文件權限 ###</p><p>文件權限在長格式每一行的開端都顯得非常的雜亂。第一個字符代表文件類型。如果是 &#39;d&#39; , 意味着它是一個目錄。如果是 &#39;-&#39; , 意味着它是一個一般文件。接下來的三個字符分別代表擁有者的可讀， 可寫 ，可執行的權限。再接着三個字符表示組成員的享有的文件權限，而最後三個字符表示其他人（既不是擁有者也不是同組）對文件的享有權限。</p><p>例如，如果有個文件在長格式下顯示為：-rw-r--r--, 這説明這是個普通文件（首字符 &#39;-&#39;），擁有者享有可讀可寫權限，但是沒有可執行權限，導致擁有者無法執行該文件（首字符&#39;-&#39;後&#39;rw-&#39;），用户組和其他用户只享有可讀權限（你不難發現&#39;r--&#39;字段在後面出現了兩次 。如果用户組是 &#39;rwx&#39; 而不是 &#39;r-&#39;，則意味着它們可讀，可寫，可執行）。</p><p>ls 的下個選項是 ls -la .. ，-a 它會列出所有的文件，包括隱藏文件。在通常情況下，隱藏文件是不可見的。用長格式列出當前工作目錄下的父目錄的所有文件。</p><h3 id="less" tabindex="-1">less <a class="header-anchor" href="#less" aria-label="Permalink to “less”">​</a></h3><p>less 是一個可以顯示你的文本文件的命令。舉例來説，你要在 /etc 下找尋名為 os-release 的文本文件。你可以使用 ls /etc 成功實現，而現在你想要閲讀它的內容。</p><p>你只需要使用 less /etc/os-release。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/Screenshot-30.-06.-2014-190252.png" alt=""></p><p>..就這樣了。</p><p>你要如何控制 less 呢?</p><p>簡單的， 你只需要動動鍵盤就行了！</p><p>less 一次只會顯示一個頁面的文本。往前翻頁你需要按 <strong>Page Up</strong>, 或者 <strong>&#39;b&#39;</strong>。往後翻頁你可以按<strong>Page Down</strong>, 或者 <strong>空格</strong>。大寫的<strong>G</strong>會跳轉到文本的末尾，<strong>1G</strong>會跳轉到文本的開端。<strong>/字符</strong>會在文本內搜索指定字符（例如，如果你輸入 /suse ，它會找尋所有文本含有的 suse 並標記出來）。n 會重複執行你的搜索，<strong>h</strong>會顯示所有的選項（h，即幫助的意思）。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/halp.jpg" alt=""></p><p>按q退出 less 命令。</p><h3 id="file" tabindex="-1">file <a class="header-anchor" href="#file" aria-label="Permalink to “file”">​</a></h3><p>file 會顯示文件的類型，是否是你要找的 ASCII 文本，還是 jpg 圖片，bash 腳本等。讓我們用 /etc/os-release 執行練習。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/06/Screenshot-30.-06.-2014-191402.png" alt=""></p><p>這樣，如你所見，os-release 是一個 ASCII 文本文件。 請嘗試其他文件，並觀察結果。</p><p>下回見了，記住…</p><p>…一定要玩的開心啊！</p><hr>`,39)),r("p",null,[e[1]||(e[1]=s("via: ",-1)),p(t,{href:"https://news.opensuse.org/2014/07/01/command-line-tuesdays-part-three/"},{default:n(()=>[...e[0]||(e[0]=[s("https://news.opensuse.org/2014/07/01/command-line-tuesdays-part-three/",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=s("譯者：",-1)),p(t,{href:"https://github.com/Luoxcat"},{default:n(()=>[...e[2]||(e[2]=[s("Luoxcat",-1)])]),_:1}),e[5]||(e[5]=s(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[s("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=s("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[s("LCTT",-1)])]),_:1}),e[9]||(e[9]=s(" 原創翻譯，",-1)),p(t,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[s("Linux中國",-1)])]),_:1}),e[10]||(e[10]=s(" 榮譽推出",-1))])])}const b=a(g,[["render",m]]);export{x as __pageData,b as default};
